practice.solution:
function discounted(priceCents: number, percent: number): number {
  return Math.round((priceCents * (100 - percent)) / 100);
}

console.log(`1999 with 10% off: ${discounted(1999, 10)}`);
console.log(`4500 with 25% off: ${discounted(4500, 25)}`);
console.log(`999 with 15% off: ${discounted(999, 15)}`);

examples.code:
function greet(name: string, greeting = "Hello"): string {
  return `${greeting}, ${name}!`;
}

console.log(greet("Ada"));
//          ^? function greet(name: string, greeting?: string): string
console.log(greet("Grace", "Welcome"));

function fullName(first: string, last?: string): string {
  if (last === undefined) {
    //^? (parameter) last: string | undefined
    return first;
  }
  return `${first} ${last}`;
  //                 ^? (parameter) last: string
}

console.log(fullName("Ada", "Lovelace"));
console.log(fullName("Cher"));

function sum(...nums: number[]): number {
  return nums.reduce((total, n) => total + n, 0);
}

const prices = [4.5, 2.25, 3];

console.log(sum(1, 2, 3));
console.log(sum(...prices));
console.log(sum());

